KIND_TEXT = {"wp": "WordPress", "ps": "PrestaShop"}

# Tema claro u oscuro de la ventana nueva (solo para ella: el escritorio no se toca)
THEME_FILE = os.path.join(LOG_DIR, "ventana-tema")
# Icono junto al reloj: «no» si se ha apagado en Configuración (sin el fichero, encendido)
TRAY_FILE = os.path.join(LOG_DIR, "ventana-bandeja")


def tray_lib():
    """El módulo del icono junto al reloj (AppIndicator de Ayatana, el de Ubuntu), o None si no está."""
    for name in ("AyatanaAppIndicator3", "AppIndicator3"):
        try:
            gi.require_version(name, "0.1")
            return getattr(__import__("gi.repository", fromlist=[name]), name)
        except (ValueError, ImportError, AttributeError):
            continue
    return None


# Abrir al iniciar sesión: el acceso de inicio de la sesión (el de «Aplicaciones al inicio» de Ubuntu), que
# abre la ventana con --al-iniciar. Solo se toca si es nuestro (lleva AUTOSTART_MARK) y un fichero normal
AUTOSTART_FILE = os.path.join(os.environ.get("XDG_CONFIG_HOME") or os.path.join(os.path.expanduser("~"), ".config"),
                              "autostart", "nexum.desktop")
AUTOSTART_MARK = "X-Nexum-Inicio=true"
# Abierta al iniciar sesión: con el icono junto al reloj, se queda en él sin enseñar la ventana
START_HIDDEN = os.environ.get("LVM_AL_INICIAR") == "1"


def autostart_read():
    """El acceso de inicio, si es un fichero normal (sin seguir enlaces); None si no está o no se puede leer."""
    try:
        fd = os.open(AUTOSTART_FILE, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    except OSError:
        return None
    with os.fdopen(fd, "rb") as f:
        if not stat.S_ISREG(os.fstat(f.fileno()).st_mode):
            return None
        return f.read(65536).decode("utf-8", "replace")


def autostart_on():
    """¿Se abre al iniciar sesión? Solo con nuestro acceso, y sin apagar a mano (Hidden o
    X-GNOME-Autostart-enabled=false, que es lo que hace «Aplicaciones al inicio» al desmarcarlo)."""
    text = autostart_read()
    if text is None or AUTOSTART_MARK not in text.splitlines():
        return False
    lines = [ln.strip().lower() for ln in text.splitlines()]
    return "hidden=true" not in lines and "x-gnome-autostart-enabled=false" not in lines


def autostart_text(script):
    """El acceso de inicio: abre la ventana de este script (con comillas si su ruta lleva espacios)."""
    exe = script if re.fullmatch(r"[A-Za-z0-9/._+-]+", script) else '"%s"' % re.sub(r'(["`$\\])', r"\\\1", script)
    return "\n".join(["[Desktop Entry]", "Type=Application", "Name=Nexum Dev Stack",
                      "Comment=Abre Nexum Dev Stack al iniciar sesión (en Configuración, General)",
                      "Exec=%s ventana --al-iniciar" % exe, "Icon=nexum", "Terminal=false",
                      "X-GNOME-Autostart-enabled=true", "X-GNOME-Autostart-Delay=5", AUTOSTART_MARK, ""])


def autostart_set(on, script):
    """Enciende (escribe nuestro acceso, 644) o apaga (borra el nuestro; uno que no sea nuestro no se toca).
    Devuelve un texto de error o None."""
    text = autostart_read()
    if os.path.lexists(AUTOSTART_FILE) and (text is None or AUTOSTART_MARK not in text.splitlines()):
        return "%s no es de Nexum Dev Stack (o es un enlace): no se toca. Quítalo o cámbialo a mano." % AUTOSTART_FILE
    try:
        if not on:
            if text is not None:
                os.unlink(AUTOSTART_FILE)
            return None
        os.makedirs(os.path.dirname(AUTOSTART_FILE), mode=0o700, exist_ok=True)
        tmp = AUTOSTART_FILE + ".nuevo"
        if os.path.lexists(tmp):
            os.unlink(tmp)
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, 0o644)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(autostart_text(script))
        os.replace(tmp, AUTOSTART_FILE)
    except OSError as exc:
        return str(exc)
    return None


def tray_wanted():
    try:
        with open(TRAY_FILE, encoding="utf-8") as f:
            return f.read().strip() != "no"
    except OSError:
        return True


def theme_exists(name):
    """¿Hay un tema GTK 3 con ese nombre (del sistema o tuyo)?"""
    if not re.fullmatch(r"[A-Za-z0-9._+-]{1,64}", name or ""):
        return False
    if name in ("Adwaita", "HighContrast"):
        return True
    return any(os.path.isdir(os.path.join(d, name, "gtk-3.0")) for d in
               ("/usr/share/themes", os.path.expanduser("~/.themes"), os.path.expanduser("~/.local/share/themes")))


PAGE_MAX = 1500


def new_page(width=860):
    """Pagina de la ventana nueva: con un ancho minimo y, con la ventana grande (maximizada), crece
    con ella hasta PAGE_MAX; a partir de ahi, centrada."""
    sw = Gtk.ScrolledWindow(hscrollbar_policy=Gtk.PolicyType.NEVER)
    content = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=18, margin=26,
                      halign=Gtk.Align.FILL)
    content.set_size_request(width, -1)
    sw.add(content)

    def fit(_w, alloc):
        side = page_side(alloc.width, [content])
        if content.get_margin_start() != side:
            content.set_margin_start(side)
            content.set_margin_end(side)
    sw.connect("size-allocate", fit)
    return sw, content


def page_side(width, boxes):
    """Margen a cada lado de una página de ancho width: lo que sobra hasta PAGE_MAX, contando con lo que pide su
    contenido (sin los márgenes de ahora). Si no se contara, un contenido más ancho que PAGE_MAX hacía crecer la
    ventana, con ella el margen y con el margen otra vez la ventana, sin parar."""
    need = PAGE_MAX
    for box in boxes:
        least = box.get_preferred_width()[0] - box.get_margin_start() - box.get_margin_end()
        need = max(need, least)
    return max(26, (width - need) // 2)


def nv_button_flow():
    """Caja de los botones del visor: en una línea si caben y, si no, en varias. Así nunca pide más ancho que el
    de su botón más ancho (con los botones grandes, una fila pedía más que la pantalla)."""
    f = css(Gtk.FlowBox(selection_mode=Gtk.SelectionMode.NONE, homogeneous=False, column_spacing=8, row_spacing=8,
                        min_children_per_line=1, max_children_per_line=40, valign=Gtk.Align.CENTER, hexpand=True),
            "nv-botonera")
    return f


def nv_flow_add(flow, w):
    flow.add(w)
    child = w.get_parent()
    if child is not None:
        child.set_can_focus(False)


def new_split_page(width=860):
    """Como new_page, en dos partes: arriba, fija (no se va al desplazar: el visor de Proyectos), y debajo lo
    que se desplaza (la lista). Devuelve (página, caja de arriba, caja de abajo, su ScrolledWindow)."""
    page = Gtk.Box(orientation=Gtk.Orientation.VERTICAL)
    top = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=18, margin_top=26, margin_bottom=14)
    top.set_size_request(width, -1)
    sw = Gtk.ScrolledWindow(hscrollbar_policy=Gtk.PolicyType.NEVER, vexpand=True)
    bottom = Gtk.Box(orientation=Gtk.Orientation.VERTICAL, spacing=18, margin_bottom=26)
    bottom.set_size_request(width, -1)
    sw.add(bottom)
    page.pack_start(top, False, False, 0)
    page.pack_start(sw, True, True, 0)

    def fit(_w, alloc):
        side = page_side(alloc.width, [top, bottom])
        for box in (top, bottom):
            if box.get_margin_start() != side:
                box.set_margin_start(side)
                box.set_margin_end(side)
    page.connect("size-allocate", fit)
    return page, top, bottom, sw


def nv_dot(on):
    return label("●", "nv-verde" if on else "nv-gris")


def nv_button(icon_name, text=None, tip=None, cb=None, *classes, flat=False):
    b = Gtk.Button(tooltip_text=tip, valign=Gtk.Align.CENTER)
    if flat:
        b.set_relief(Gtk.ReliefStyle.NONE)
    box = Gtk.Box(spacing=6)
    if icon_name is not None:
        box.pack_start(icon_name if isinstance(icon_name, Gtk.Widget) else icon(icon_name), False, False, 0)
    if text:
        box.pack_start(Gtk.Label(label=text), False, False, 0)
    b.add(box)
    css(b, *classes)
    if cb:
        b.connect("clicked", cb)
    return b


def kind_icon(kind, size=18):
    return logo({"wp": "wordpress", "ps": "prestashop"}[kind], size) if kind in ("wp", "ps") \
        else icon("folder-symbolic", size)


class Hamburger(Gtk.DrawingArea):
    """Icono del menu: tres rayas, algo mas anchas que las del tema, del color del texto."""

    def __init__(self, width=20, height=16):
        super().__init__()
        self.set_size_request(width, height)

    def do_draw(self, cr):
        c = self.get_style_context().get_color(self.get_state_flags())
        cr.set_source_rgba(c.red, c.green, c.blue, c.alpha)
        w, h = self.get_allocated_width(), self.get_allocated_height()
        cr.set_line_width(2)
        cr.set_line_cap(1)  # (extremos redondeados)
        for y in (h / 2 - 5, h / 2, h / 2 + 5):
            cr.move_to(1, round(y) + 0.5)
            cr.line_to(w - 1, round(y) + 0.5)
        cr.stroke()
        return False


class NvBandeja:
    """El icono junto al reloj."""

    # ------------------------------------------------------------------ icono junto al reloj
    def nv_tray_setup(self):
        """El icono junto al reloj (si está encendido en Configuración y hay AppIndicator): abrir la ventana,
        arrancar o parar la versión activa, abrir web.local y salir."""
        if self.tray is not None or not tray_wanted():
            return
        lib = tray_lib()
        if lib is None:
            return
        ind = lib.Indicator.new(APP_ID, self.icon, lib.IndicatorCategory.APPLICATION_STATUS)
        ind.set_title("Nexum Dev Stack")
        menu = Gtk.Menu()

        def add(key, text, cb=None):
            item = Gtk.MenuItem(label=text)
            if cb:
                item.connect("activate", lambda *_: cb())
            else:
                item.set_sensitive(False)
            menu.append(item)
            self.tray_items[key] = item
        add("open", "Abrir Nexum Dev Stack", self.nv_tray_open)
        menu.append(Gtk.SeparatorMenuItem())
        add("state", "Ninguna versión activa")
        add("power", "Arrancar", self.nv_tray_power)
        add("web", "Abrir web.local", self.nv_tray_web)
        menu.append(Gtk.SeparatorMenuItem())
        add("quit", "Salir", self.nv_tray_quit)
        menu.show_all()
        ind.set_menu(menu)
        ind.set_secondary_activate_target(self.tray_items["open"])
        ind.set_status(lib.IndicatorStatus.ACTIVE)
        self.tray = (lib, ind, menu)
        self.nv_tray_update()

    def nv_tray_remove(self):
        if self.tray is None:
            return
        lib, ind, _menu = self.tray
        ind.set_status(lib.IndicatorStatus.PASSIVE)
        self.tray, self.tray_items = None, {}

    def nv_tray_update(self):
        if self.tray is None:
            return
        d = self.data or {}
        act = d.get("active") or ""
        it = self.tray_items
        if not act:
            it["state"].set_label("Ninguna versión activa")
            it["power"].set_label("Elegir una versión…")
        else:
            it["state"].set_label("● lampp-%s en marcha" % act if d.get("running") else "○ lampp-%s parada" % act)
            it["power"].set_label("Parar y desactivar" if d.get("running") else "Arrancar lampp-%s" % act)
        busy_guard(it["power"], self.busy).set_sensitive(bool(d))
        link = (self.projects or {}).get("link") or ""
        it["web"].set_label("Abrir %s" % (link or "web.local"))
        it["web"].set_sensitive(bool(link) and bool(d.get("running")))

    def nv_tray_hide(self):
        """La X de la ventana: con el icono, la esconde (True: no se cierra); sin él, se cierra como siempre."""
        if self.tray is None:
            return False
        self.win.hide()
        return True

    def nv_tray_open(self):
        self.win.present()
        # (al volver, sus datos al momento: escondida solo se preguntaba lo del menú)
        if not self.busy:
            run_quick(["gui-vuelta"], self.on_round)

    def nv_tray_power(self):
        if not (self.data or {}).get("active"):
            self.nv_tray_open()
        self.nv_power()

    def nv_tray_web(self):
        if self.project_web():
            self.open_uri(self.project_web())

    def nv_tray_quit(self):
        self.nv_tray_remove()
        self.win.destroy()

    def nv_tray_toggle(self, sw, _p):
        on = sw.get_active()
        try:
            os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
            with open(TRAY_FILE, "w", encoding="utf-8") as f:
                f.write("si\n" if on else "no\n")
        except OSError as exc:
            message(self.win, "No se ha podido guardar", str(exc), Gtk.MessageType.ERROR)
            return
        if on:
            self.nv_tray_setup()
        else:
            self.nv_tray_remove()

    def nv_autostart_toggle(self, sw, _p):
        """Configuración, Programa: abrir al iniciar sesión (en simulación no se escribe nada)."""
        on = sw.get_active()
        if on == autostart_on():
            return
        if SIMULATE:
            self.toast("[simulación] %s %s" % ("Se escribiría" if on else "Se quitaría", AUTOSTART_FILE))
            return
        err = autostart_set(on, SCRIPT)
        if err:
            message(self.win, "No se ha podido cambiar el inicio de sesión", err, Gtk.MessageType.ERROR)
            sw.handler_block_by_func(self.nv_autostart_toggle)
            sw.set_active(autostart_on())
            sw.handler_unblock_by_func(self.nv_autostart_toggle)
            return
        self.toast("Se abrirá al iniciar sesión" if on else "Ya no se abre al iniciar sesión")

    def nv_exit(self):
        """Al cerrar la última ventana: se sale y, si algo lo retuviera (un bucle, un hilo, una orden que
        no acaba), a los 5 s se corta el proceso. Nunca queda un Nexum en marcha sin ventana."""
        self.quit()

        def watchdog():
            time.sleep(5)
            os._exit(0)
        threading.Thread(target=watchdog, daemon=True).start()

    def auto_check_package(self):
        if self.data is None or self.busy:
            return True
        if self.update_check_due():
            self.check_package(auto=True)
            # (y los parches de los componentes, un poco después: sin juntarse con el aviso del programa)
            GLib.timeout_add_seconds(25, self.nv_components_auto)
        return False

    def update_check_due(self):
        """¿Toca buscar una versión nueva al abrir? El primer arranque de cada día y, después, cada
        UPDATE_EVERY arranques. Se lleva en ~/.nexum/actualizaciones-arranques: fecha y los
        arranques desde la última vez que se buscó."""
        path = os.path.join(LOG_DIR, "actualizaciones-arranques")
        today = time.strftime("%Y-%m-%d")
        if SIMULATE:
            return True
        try:
            with open(path, encoding="utf-8") as fh:
                day, _, n = fh.read(40).strip().partition(" ")
            n = int(n)
        except (OSError, ValueError):
            day, n = "", 0
        due = day != today or n + 1 >= UPDATE_EVERY
        try:
            os.makedirs(LOG_DIR, mode=0o700, exist_ok=True)
            with open(path + ".nuevo", "w", encoding="utf-8") as fh:
                fh.write("%s %d\n" % (today, 0 if due else n + 1))
            os.replace(path + ".nuevo", path)
        except OSError:
            pass
        return due

