                            *([] if up else ["nv-tenue"])), False, False, 0)
        top.pack_end(st, False, False, 0)
        card.pack_start(top, False, False, 0)
        card.pack_start(css(Gtk.Box(), "nv-pie"), False, False, 0)
        acts = Gtk.Box(spacing=8)
